from collections import deque
def is_bipartite(adj, n):
    color = [-1] * n
    for start in range(n):
        if color[start] != -1:
            continue                       # already handled
        color[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if color[v] == -1:
                    color[v] = color[u] ^ 1
                    q.append(v)
                elif color[v] == color[u]:
                    return False           # clash on an edge
    return True

