boolean isBipartite(List<List<Integer>> adj, int n) {
    int[] color = new int[n];
    Arrays.fill(color, -1);
    for (int start = 0; start < n; start++) {
        if (color[start] != -1) continue;   // already handled
        Queue<Integer> q = new LinkedList<>();
        q.add(start); color[start] = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj.get(u)) {
                if (color[v] == -1) { color[v] = color[u] ^ 1; q.add(v); }
                else if (color[v] == color[u]) return false;   // clash on an edge
            }
        }
    }
    return true;
}

