function isBipartite(adj, n) {
  const color = new Array(n).fill(-1);
  for (let start = 0; start < n; start++) {
    if (color[start] !== -1) continue;   // already handled
    const q = [start]; color[start] = 0;
    while (q.length) {
      const u = q.shift();
      for (const v of adj[u]) {
        if (color[v] === -1) { color[v] = color[u] ^ 1; q.push(v); }
        else if (color[v] === color[u]) return false;   // clash on an edge
      }
    }
  }
  return true;
}

