bool dfs(int u, int c, vector<vector<int>>& adj, vector<int>& color) {
    color[u] = c;
    for (int v : adj[u]) {
        if (color[v] == -1) {
            if (!dfs(v, c ^ 1, adj, color)) return false;
        } else if (color[v] == c) {
            return false;   // same color across an edge
        }
    }
    return true;
}

